  const pageId = "0:1";
  const page = await figma.getNodeByIdAsync(pageId);
  if (!page) {
    console.log("Page not found");
    return;
  }

  // Let's find all text nodes in page 0:1
  const textNodes = page.findAll(node => node.type === "TEXT");
  const texts = textNodes.map(node => {
    return {
      id: node.id,
      name: node.name,
      characters: node.characters,
      x: node.absoluteTransform[0][2],
      y: node.absoluteTransform[1][2]
    };
  });

  // Sort by vertical position (y) first, then horizontal (x) to make it readable
  texts.sort((a, b) => {
    if (Math.abs(a.y - b.y) < 20) {
      return a.x - b.x;
    }
    return a.y - b.y;
  });

  console.log(JSON.stringify(texts.slice(0, 50), null, 2));
}
run();

